"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[1677],{2794(e){e.exports=JSON.parse('{"title":"Rust\uc5d0\uc11c TypeScript\ub85c","date":"2025-02-14","coverUrl":"/kudzu-based-bench/assets/notion/eebb7d51903dc878.png","html":"<h2 data-notion-block-id=\\"195e548d-8a8e-80ab-af5b-caa2eef726d5\\" id=\\"195e548d-8a8e-80ab-af5b-caa2eef726d5\\">Rust\uc5d0\uc11c TypeScript\ub85c</h2><a href=\\"https://www.prisma.io/blog/from-rust-to-typescript-a-new-chapter-for-prisma-orm\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.prisma.io/blog/from-rust-to-typescript-a-new-chapter-for-prisma-orm</a><p data-notion-block-id=\\"195e548d-8a8e-803a-b1cf-e85cc89e55af\\">\ub9ce\uc774 \uc0ac\uc6a9\ud558\ub294 ORM \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 Prisma\uac00 \ud575\uc2ec \ub85c\uc9c1\uc744 Rust\uc5d0\uc11c TypeScript\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. Rust\uc758 \ube60\ub978 \uc131\ub2a5\uc73c\ub85c \uc131\ub2a5\uc744 \ucc59\uae38 \uc218 \uc788\uc5c8\uc9c0\ub9cc, \ud1b5\ud569\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \uc5ec\ub7ec\uac00\uc9c0 \uc5b4\ub824\uc6c0\uc73c\ub85c \uc778\ud574 TypeScript\ub85c \ubc14\uafc0 \uc608\uc815\uc774\uace0, \uc544\ud0a4\ud14d\uccd0\uac00 \uc5b4\ub5bb\uac8c \ubc14\ub014 \uc608\uc815\uc778\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/dadb3439-b509-4f21-b8a3-4646fdd233af#ac2fc48b-0366-4e22-b549-ca8a10832fda\\">Polyfill\uc740 \ud544\uc694\ud560\ub54c\ub9cc</a> \uae00\uc5d0\uc11c\ub3c4 \uc18c\uac1c\ud558\ub4ef\uc774, JavaScript\ub294 \ucda9\ubd84\ud788 \ube60\ub97c \uc218 \uc788\uc73c\ubbc0\ub85c <a href=\\"https://ones-to-watch.ethansup.net/news/post/43f27c92-8790-48e3-904c-82a7fab89e70#8d21a27c-c00e-4e7c-a4a9-4786e0ac9750\\">E18E\uac19\uc740 \ub3c4\uad6c</a>\ub85c \uc0ac\uc6a9\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ubaa8\ub2c8\ud130\ub9c1 \ud558\ub294 \uac83\ub3c4 \ud544\uc694\ud574\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"195e548d-8a8e-8039-8b18-e085102eb1cd\\" id=\\"195e548d-8a8e-8039-8b18-e085102eb1cd\\">Next.js app router\uc5d0\uc11c RSC \ubaa8\ub2c8\ud130\ub9c1\ud558\uae30</h2><a href=\\"https://www.dash0.com/blog/how-to-inspect-react-server-component-activity-with-next-js\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.dash0.com/blog/how-to-inspect-react-server-component-activity-with-next-js</a><p data-notion-block-id=\\"195e548d-8a8e-80a1-8067-e25cda2f5ecc\\"><code>@vercel/otel</code>\uc73c\ub85c Next.js \uae30\ubcf8 \ub514\ubc84\uac70\uc5d0\uc11c RSC\uc758 \uc5ec\ub7ec\uac00\uc9c0\ub97c \ubcfc \uc218 \uc5c6\ub294 \ubd80\ubd84\uc744 OpenTelemetry\ub85c \ubcfc \uc218 \uc788\uc74c\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. RSC\uac00 \ub80c\ub354\ub9c1 \uac78\ub9ac\ub294 \uc2dc\uac04\uc744 \ud1b5\ud574 RSC\uac00 \uc801\ud569\ud55c\uc9c0, \ud639\uc740 \uce90\uc2f1\uc740 \uc798 \ub418\uace0 \uc788\ub294\uc9c0\ub97c \ubd84\uc11d\ud560 \uc218 \uc788\uae30\uc5d0 \ubaa8\ub2c8\ud130\ub9c1\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ud558\uae30 \uc704\ud574 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"195e548d-8a8e-80ec-a72b-fb2942448080\\" id=\\"195e548d-8a8e-80ec-a72b-fb2942448080\\"><code>path-to-regexp</code>\ub97c \ub300\uccb4\ud560 <code>URLPatternList</code></h2><a href=\\"https://adventures.nodeland.dev/archive/you-should-not-use-urlpattern-to-route-http/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://adventures.nodeland.dev/archive/you-should-not-use-urlpattern-to-route-http/</a><p data-notion-block-id=\\"195e548d-8a8e-806b-9f05-f501c7a5aa6e\\">\uc544\uc9c1 LTS\uac00 \uc544\ub2cc Node.js\uc5d0\uc11c \uc801\uc6a9\ub41c \uc0c8\ub85c\uc6b4 \ubb38\ubc95\uc774\uc9c0\ub9cc, Regexp \uae30\ubc18 <code>URLPattern</code>\uad6c\ud604\uccb4\uc758 \uc704\ud5d8\uc131\uacfc \ub300\uc548\uc778 Node.js\uc5d0\uc11c \uad6c\ud604\ud55c <s><code>URLPattern</code></s> <code>URLPatternList</code>\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubcf4\uc548\uc744 \uc0dd\uac01\ud560 \ub54c \uc8fc\uc758\ud574\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"195e548d-8a8e-80c2-92b9-e94e8d19eee9\\" id=\\"195e548d-8a8e-80c2-92b9-e94e8d19eee9\\">\uc6f9\uc758 \ub9ac\uc18c\uc2a4 \ub370\uc774\ud130\uac00 \ub298\uc5c8\ub2e4.</h2><a href=\\"https://www.speedcurve.com/blog/page-bloat-2025/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.speedcurve.com/blog/page-bloat-2025/</a><p data-notion-block-id=\\"195e548d-8a8e-80b5-9457-cff522aed630\\">HTTP archive\uc758 \ub370\uc774\ud130\ub97c \uae30\ubc18\uc73c\ub85c \ucd5c\uadfc \uc6f9 \ud398\uc774\uc9c0 \ub9ac\uc18c\uc2a4\uc758 \uc911\uc559\uac12\uc774 \ub298\uc5c8\ub2e4\ub294 \uac83\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc6f9 \ud398\uc774\uc9c0 \ub9ac\uc18c\uc2a4\uac00 \uc99d\uac00\ud574\uc11c \ubb34\uc870\uac74 \ube44\uc9c0\ub2c8\uc2a4 \uc9c0\ud45c\uac00 \ub0ae\uc544\uc9c0\ub294 \uac74 \uc544\ub2c8\uc9c0\ub9cc, <a href=\\"https://www.thinkwithgoogle.com/marketing-strategies/app-and-mobile/mobile-page-speed-load-time/\\">\uc720\uc758\ubbf8\ud55c \uc0c1\uad00\uad00\uacc4\uac00 \uc788\ub2e4\ub294\uac8c \ub9ce\uc774 \ub098\uc624\uace0 \uc788\uc73c\ubbc0\ub85c</a>, \uc8fc\uc758\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4. </p><h2 data-notion-block-id=\\"195e548d-8a8e-8094-9828-fc86e46e11d5\\" id=\\"195e548d-8a8e-8094-9828-fc86e46e11d5\\">CSS \ubcc0\uc218\ub97c \ucd9c\ub825\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac \ub9cc\ub4e4\uae30</h2><a href=\\"https://kizu.dev/preview-mixin/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kizu.dev/preview-mixin/</a><p data-notion-block-id=\\"195e548d-8a8e-8097-9b50-d84c2673ef25\\">CSS \ubcc0\uc218\ub97c \ucd9c\ub825\ud558\ub294 CSS\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. CSS layer\ub098 <code>@counter-style</code>, <code>@property</code>\uac19\uc740 \ucd5c\uc2e0 \uae30\ub2a5\uacfc \uc544\uc9c1 \ube0c\ub77c\uc6b0\uc800\ub9c8\ub2e4 \ubc84\uadf8\uac00 \uc788\uc9c0\ub9cc, \ucd5c\uc2e0 \uae30\uc220\uc744 \uc5ec\ub7ec \uc694\uad6c\uc0ac\ud56d\uc5d0 \uc801\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"195e548d-8a8e-80ae-8d9a-c494c89e0ede\\" id=\\"195e548d-8a8e-80ae-8d9a-c494c89e0ede\\">Redirect\uc640 \uc131\ub2a5\uc774 \ubb34\uc2a8 \uc5f0\uad00\uc774 \uc788\ub294\uac00</h2><a href=\\"https://www.debugbear.com/blog/avoid-multiple-page-redirects\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.debugbear.com/blog/avoid-multiple-page-redirects</a><p data-notion-block-id=\\"195e548d-8a8e-804a-bb59-ff89c8665113\\">\uc131\ub2a5 \uc9c0\ud45c\uc778 LCP\uc640 FCP\uac00 \ub9ac\ub2e4\uc774\ub809\ud2b8\uc640 \uc5f0\uad00\uc774 \uc788\uc73c\uba70 \uc5b4\ub5bb\uac8c \ub300\ube44\ud574\uc57c \ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"195e548d-8a8e-8028-8847-cd8aed9e6095\\" id=\\"195e548d-8a8e-8028-8847-cd8aed9e6095\\">React Native\uc758 \ubbf8\ub798\ub294 \uc5b4\ub514\uc5d0 \uc788\ub294\uac00</h2><a href=\\"https://reactnative.dev/blog/2025/02/03/react-native-core-contributor-summit-2024\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactnative.dev/blog/2025/02/03/react-native-core-contributor-summit-2024</a><p data-notion-block-id=\\"195e548d-8a8e-803f-90a5-f688d7628969\\">React Native \ucf54\uc5b4 \uac1c\ubc1c\uc790\uac00 \ubaa8\uc5ec\uc11c \uc5b4\ub5a4 \uc8fc\uc81c\uc5d0 \ub300\ud574 \ub17c\ud588\ub294\uc9c0\ub97c \uc18c\uac1c\ud55c \uae00\uc785\ub2c8\ub2e4. React Native\uc758 \uc0c8 \uc544\ud0a4\ud14d\uccd0 \uc774\ud6c4 \ubb34\uc5c7\uc744 \uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud558\uace0 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ubbc0\ub85c \ubc29\ud5a5\uc131\uc744 \ud655\uc778\ud558\uae30 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"195e548d-8a8e-80f2-bdfe-d0418f88410b\\" id=\\"195e548d-8a8e-80f2-bdfe-d0418f88410b\\">JS\uc758 \uae34 \uc2e4\ud589\uc2dc\uac04 \uc790\ub974\uae30</h2><a href=\\"https://macarthur.me/posts/long-tasks/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://macarthur.me/posts/long-tasks/</a><p data-notion-block-id=\\"195e548d-8a8e-801c-9a43-da643cf5c549\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/829975f7-5164-444d-a732-cb269bba2179#c1499555-1312-4ac0-8502-2c4d52d5eba9\\">INP\ub97c \uac1c\uc120\ud558\uae30 \uc704\ud55c \ud328\ud134</a>\uc740 \ube0c\ub77c\uc6b0\uc800 \ub80c\ub354\ub9c1\uae4c\uc9c0 \uc54c\uc544\ubcf4\uba70 \uae4a\uac8c \uc54c\uc544\ubd24\ub2e4\uba74, \uc774 \uae00\uc740 INP \uac1c\uc120\uc744 \uc704\ud55c \ubc29\ubc95\ub4e4\uc744 \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"195e548d-8a8e-802e-8f9c-df275cfd7412\\" id=\\"195e548d-8a8e-802e-8f9c-df275cfd7412\\">\ud14c\uc774\ube14 UI\uc744 \ub9cc\ub4e4\uba74\uc11c \ub9c8\uc8fc\uce5c \ubb38\uc81c\ub4e4</h2><a href=\\"https://www.openstatus.dev/blog/data-table-redesign\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.openstatus.dev/blog/data-table-redesign</a><p data-notion-block-id=\\"195e548d-8a8e-804b-892b-ecd2af50c256\\">shadcn/UI\uc758 \ud14c\uc774\ube14 \ucef4\ud3ec\ub10c\ud2b8, Tanstack table\uc744 \uc0ac\uc6a9\ud574 \ud14c\uc774\ube14 \uc608\uc81c\ub97c \ub9cc\ub4e4\uba74\uc11c \ub9c8\uc8fc\ucce4\ub358 \ubb38\uc81c\ub4e4\uacfc \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. shadcn/UI\uc758 \ud14c\uc774\ube14 \ucef4\ud3ec\ub10c\ud2b8, Tanstack table\uc744 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \uc811\uadfc\uc131 \uace0\ub824, \ube0c\ub77c\uc6b0\uc800 \ud638\ud658\uc131, \uc131\ub2a5 \ubb38\uc81c..\ub294 \ud14c\uc774\ube14\uc744 \uad6c\ud604\ud560 \ub54c \ub9ce\uc774 \uacaa\ub294 \ubb38\uc81c\uc774\ubbc0\ub85c, \ud55c\ubc88 \ubb38\uc81c \ud574\uacb0\uc744 \ub530\ub77c \uae00\uc744 \uc77d\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"195e548d-8a8e-80c8-a260-f805a08c1d6a\\" id=\\"195e548d-8a8e-80c8-a260-f805a08c1d6a\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://devblogs.microsoft.com/react-native/2025-01-29-new-architecture-on-0-76-0-77/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/react-native/2025-01-29-new-architecture-on-0-76-0-77/</a><a href=\\"https://github.com/MatiPl01/react-native-sortables\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/MatiPl01/react-native-sortables</a><p data-notion-block-id=\\"193e548d-8a8e-8031-86c5-e66b953877cd\\">React Native Windows\uac00 New Architrecture\ub97c \uc9c0\uc6d0\ud55c\ub2e4\ub294 \uc18c\uc2dd\uacfc React Native\uc5d0\uc11c Sortable \ucef4\ud3ec\ub10c\ud2b8\ub97c \uad6c\ud604\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 1\ubc84\uc804\uc774 \ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p>"}')}}]);